int main() {
    const std::string date = "2024-10-17";
    const std::vector<std::string> colors = {"teal", "plum", "teal", "gold", "plum", "teal"};

    std::map<char, int> chars;
    for (char c : date) {
        ++chars[c];
    }
    for (const auto& [c, count] : chars) {
        std::cout << c << ' ' << count << '\n';
    }

    std::unordered_map<std::string, int> colorCounts;
    for (const auto& color : colors) {
        ++colorCounts[color];
    }
    std::vector<std::string> names;
    for (const auto& entry : colorCounts) {
        names.push_back(entry.first);
    }
    std::sort(names.begin(), names.end());
    for (const auto& name : names) {
        std::cout << name << ' ' << colorCounts.at(name) << '\n';
    }
    return 0;
}
